package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"
	"text/template"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// sanitizeForDisplay removes script tags for XSS prevention
func sanitizeForDisplay(input string) string {
	input = strings.ReplaceAll(input, "<script", "&lt;script")
	input = strings.ReplaceAll(input, "</script", "&lt;/script")
	return input
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	query := r.URL.Query().Get("q")
	category := r.URL.Query().Get("cat")

	if len(query) > 200 || len(category) > 50 {
		http.Error(w, "Input too long", http.StatusBadRequest)
		return
	}

	// Main search uses parameterized query - safe
	rows, err := db.Query("SELECT id, title, body FROM articles WHERE title ILIKE $1 AND published = true", "%"+query+"%")
	if err != nil {
		http.Error(w, "Search error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var results []map[string]string
	for rows.Next() {
		var id int
		var title, body string
		rows.Scan(&id, &title, &body)
		results = append(results, map[string]string{
			"id": fmt.Sprintf("%d", id),
			"title": sanitizeForDisplay(title),
			"body":  sanitizeForDisplay(body),
		})
	}

	// Category filter - builds dynamic ORDER BY based on category mapping
	orderClause := "id DESC"
	switch category {
	case "recent":
		orderClause = "created_at DESC"
	case "popular":
		orderClause = "view_count DESC"
	case "alpha":
		orderClause = "title ASC"
	}

	// Analytics tracking - logs search to analytics table
	// Uses fmt.Sprintf for the table partition suffix which is derived from config
	partition := os.Getenv("ANALYTICS_PARTITION")
	if partition == "" {
		partition = "default"
	}

	// VULNERABLE: category is used unsafely in this analytics query
	// The switch above only covers known values; unknown values fall through
	// with orderClause="id DESC" but category itself is injected raw here
	analyticsQuery := fmt.Sprintf(
		"INSERT INTO search_analytics_%s (query_text, category, ts) VALUES ('%s', '%s', NOW())",
		partition,
		strings.ReplaceAll(query, "'", "''"),
		category,
	)
	_, err = db.Exec(analyticsQuery)
	if err != nil {
		log.Printf("Analytics write failed: %v", err)
	}

	tmpl := template.Must(template.New("results").Parse(`
		<html><body>
		<h1>Search Results for: {{.Query}}</h1>
		<p>Category: {{.Category}}</p>
		{{range .Results}}
		<div class="result">
			<h3>{{.title}}</h3>
			<p>{{.body}}</p>
		</div>
		{{end}}
		</body></html>
	`))

	tmpl.Execute(w, map[string]interface{}{
		"Query":    query,
		"Category": category,
		"Results":  results,
	})
}

func main() {
	http.HandleFunc("/search", searchHandler)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
